window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-db3e967f9152f14c"]={"versions": [{"id": "FIG-db3e967f9152f14c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Struktur für Instanzreferenzen auf Variablenelemente (<code>AutosarVariableInstance</code>) in der AUTOSAR-Architektur (AUTOSAR_TPS_TimingExtensions). Es definiert die strukturellen Zusammenhänge und Kontextpfade, um eine konkrete Datenvariable innerhalb einer Komponenten- und Dekompositionshierarchie über einen <code>InstanceRef</code>-Mechanismus (<code>VariableInComponentInstanceRef</code>) eindeutig zu adressieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernklassen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>AutosarVariableInstance</strong> («Identifiable»): Aggregiert via Komposition genau eine Instanzreferenz (<code>+variableInstance 1</code>) vom Typ <code>VariableInComponentInstanceRef</code>.\n</li><li><strong>VariableInComponentInstanceRef</strong> («AtpInstanceRef», Package <code>InstanceRefs</code>): Spezialisierte Instanzreferenzklasse, die über folgende Rollen verfügt:\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität 1, Stereotyp «atpDerived», Tag <code>{redefines atpBase}</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>SwComponentPrototype</code>.\n</li><li><code>+contextPortPrototype</code>: Multiplizität 1, Tag <code>{subsets atpContextElement}</code>, referenziert <code>PortPrototype</code>.\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, Tag <code>{subsets atpContextElement}</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität 1, Tag <code>{redefines atpTarget}</code>, referenziert <code>DataPrototype</code>.\n</li></ul>\n</li><li><strong>SwComponentType</strong> («ARElement», «AtpBlueprint», «AtpBlueprintable», «AtpType», Package <code>Components</code>).\n</li><li><strong>SwComponentPrototype</strong> («AtpPrototype», Package <code>Composition</code>): Besitzt Assoziation <code>+type 1 {redefines atpType}</code> mit Stereotyp «isOfType» auf <code>SwComponentType</code>.\n</li><li><strong>PortPrototype</strong> («AtpBlueprintable», «AtpPrototype», Package <code>Components</code>).\n</li><li><strong>DataPrototype</strong> («AtpPrototype», Package <code>DataPrototypes</code>): Abstrakte Basisklasse, von der <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code> erben.\n</li><li><strong>AutosarDataPrototype</strong> (Package <code>DataPrototypes</code>): Generalisierung für <code>VariableDataPrototype</code>.\n</li><li><strong>VariableDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>AutosarDataPrototype</code>.\n</li><li><strong>ApplicationCompositeElementDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>DataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenzablauf oder zeitliches Protokoll dargestellt. Die Instanzreferenz bildet zur Laufzeit- bzw. Modellierungsphase einen geordneten Pfad («AtpInstanceRef») ab: Ausgehend von der Basis (<code>SwComponentType</code>) wird über eine Folge von Subkomponenten-Instanzen (<code>contextComponent</code>), einen konkreten Port (<code>contextPortPrototype</code>), optional ein Wurzel-Datenelement (<code>rootVariableDataPrototype</code>) sowie tiefer geschachtelte Datenelementstrukturen (<code>contextDataPrototype</code>) auf das finale Ziel-Datenelement (<code>targetDataProtoype</code>) traversiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Werkzeuge und Modelltransformatoren, die Instanzen von Variablen innerhalb von AUTOSAR-Software-Komponenten für Timing-Beschreibungen referenzieren. Wesentliche Modellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Jede <code>AutosarVariableInstance</code> muss exakt eine <code>VariableInComponentInstanceRef</code> besitzen.\n</li><li>Das Ziel (<code>targetDataProtoype</code>) ist strikt einfach (<code>1</code>) und redefiniert <code>atpTarget</code>.\n</li><li>Der Kontextpfad erfordert zwingend genau einen <code>PortPrototype</code> (<code>contextPortPrototype 1</code>).\n</li><li>Schachtelungen über Komponenten (<code>contextComponent</code>) und hierarchische Datenelemente (<code>contextDataPrototype</code>) sind geordnet (<code>{ordered}</code>) und als Teilmengen von <code>atpContextElement</code> modelliert.\n</li><li><code>base</code> ist abgeleitet (<code>«atpDerived»</code>) und redefiniert <code>atpBase</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d703ea284e87bdea", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Struktur für Instanzreferenzen auf Variablenelemente (<code>AutosarVariableInstance</code>) in der AUTOSAR-Architektur (AUTOSAR_TPS_TimingExtensions). Es definiert die strukturellen Zusammenhänge und Kontextpfade, um eine konkrete Datenvariable innerhalb einer Komponenten- und Dekompositionshierarchie über einen <code>InstanceRef</code>-Mechanismus (<code>VariableInComponentInstanceRef</code>) eindeutig zu adressieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernklassen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>AutosarVariableInstance</strong> («Identifiable»): Aggregiert via Komposition genau eine Instanzreferenz (<code>+variableInstance 1</code>) vom Typ <code>VariableInComponentInstanceRef</code>.\n</li><li><strong>VariableInComponentInstanceRef</strong> («AtpInstanceRef», Package <code>InstanceRefs</code>): Spezialisierte Instanzreferenzklasse, die über folgende Rollen verfügt:\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität 1, Stereotyp «atpDerived», Tag <code>{redefines atpBase}</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>SwComponentPrototype</code>.\n</li><li><code>+contextPortPrototype</code>: Multiplizität 1, Tag <code>{subsets atpContextElement}</code>, referenziert <code>PortPrototype</code>.\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, Tag <code>{subsets atpContextElement}</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität 1, Tag <code>{redefines atpTarget}</code>, referenziert <code>DataPrototype</code>.\n</li></ul>\n</li><li><strong>SwComponentType</strong> («ARElement», «AtpBlueprint», «AtpBlueprintable», «AtpType», Package <code>Components</code>).\n</li><li><strong>SwComponentPrototype</strong> («AtpPrototype», Package <code>Composition</code>): Besitzt Assoziation <code>+type 1 {redefines atpType}</code> mit Stereotyp «isOfType» auf <code>SwComponentType</code>.\n</li><li><strong>PortPrototype</strong> («AtpBlueprintable», «AtpPrototype», Package <code>Components</code>).\n</li><li><strong>DataPrototype</strong> («AtpPrototype», Package <code>DataPrototypes</code>): Abstrakte Basisklasse, von der <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code> erben.\n</li><li><strong>AutosarDataPrototype</strong> (Package <code>DataPrototypes</code>): Generalisierung für <code>VariableDataPrototype</code>.\n</li><li><strong>VariableDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>AutosarDataPrototype</code>.\n</li><li><strong>ApplicationCompositeElementDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>DataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenzablauf oder zeitliches Protokoll dargestellt. Die Instanzreferenz bildet zur Laufzeit- bzw. Modellierungsphase einen geordneten Pfad («AtpInstanceRef») ab: Ausgehend von der Basis (<code>SwComponentType</code>) wird über eine Folge von Subkomponenten-Instanzen (<code>contextComponent</code>), einen konkreten Port (<code>contextPortPrototype</code>), optional ein Wurzel-Datenelement (<code>rootVariableDataPrototype</code>) sowie tiefer geschachtelte Datenelementstrukturen (<code>contextDataPrototype</code>) auf das finale Ziel-Datenelement (<code>targetDataProtoype</code>) traversiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Werkzeuge und Modelltransformatoren, die Instanzen von Variablen innerhalb von AUTOSAR-Software-Komponenten für Timing-Beschreibungen referenzieren. Wesentliche Modellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Jede <code>AutosarVariableInstance</code> muss exakt eine <code>VariableInComponentInstanceRef</code> besitzen.\n</li><li>Das Ziel (<code>targetDataProtoype</code>) ist strikt einfach (<code>1</code>) und redefiniert <code>atpTarget</code>.\n</li><li>Der Kontextpfad erfordert zwingend genau einen <code>PortPrototype</code> (<code>contextPortPrototype 1</code>).\n</li><li>Schachtelungen über Komponenten (<code>contextComponent</code>) und hierarchische Datenelemente (<code>contextDataPrototype</code>) sind geordnet (<code>{ordered}</code>) und als Teilmengen von <code>atpContextElement</code> modelliert.\n</li><li><code>base</code> ist abgeleitet (<code>«atpDerived»</code>) und redefiniert <code>atpBase</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2ef3eb2e618bf6a0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Struktur für Instanzreferenzen auf Variablenelemente (<code>AutosarVariableInstance</code>) in der AUTOSAR-Architektur (AUTOSAR_TPS_TimingExtensions). Es definiert die strukturellen Zusammenhänge und Kontextpfade, um eine konkrete Datenvariable innerhalb einer Komponenten- und Dekompositionshierarchie über einen <code>InstanceRef</code>-Mechanismus (<code>VariableInComponentInstanceRef</code>) eindeutig zu adressieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernklassen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>AutosarVariableInstance</strong> («Identifiable»): Aggregiert via Komposition genau eine Instanzreferenz (<code>+variableInstance 1</code>) vom Typ <code>VariableInComponentInstanceRef</code>.\n</li><li><strong>VariableInComponentInstanceRef</strong> («AtpInstanceRef», Package <code>InstanceRefs</code>): Spezialisierte Instanzreferenzklasse, die über folgende Rollen verfügt:\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität 1, Stereotyp «atpDerived», Tag <code>{redefines atpBase}</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>SwComponentPrototype</code>.\n</li><li><code>+contextPortPrototype</code>: Multiplizität 1, Tag <code>{subsets atpContextElement}</code>, referenziert <code>PortPrototype</code>.\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, Tag <code>{subsets atpContextElement}</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, Tags <code>{ordered, subsets atpContextElement}</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität 1, Tag <code>{redefines atpTarget}</code>, referenziert <code>DataPrototype</code>.\n</li></ul>\n</li><li><strong>SwComponentType</strong> («ARElement», «AtpBlueprint», «AtpBlueprintable», «AtpType», Package <code>Components</code>).\n</li><li><strong>SwComponentPrototype</strong> («AtpPrototype», Package <code>Composition</code>): Besitzt Assoziation <code>+type 1 {redefines atpType}</code> mit Stereotyp «isOfType» auf <code>SwComponentType</code>.\n</li><li><strong>PortPrototype</strong> («AtpBlueprintable», «AtpPrototype», Package <code>Components</code>).\n</li><li><strong>DataPrototype</strong> («AtpPrototype», Package <code>DataPrototypes</code>): Abstrakte Basisklasse, von der <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code> erben.\n</li><li><strong>AutosarDataPrototype</strong> (Package <code>DataPrototypes</code>): Generalisierung für <code>VariableDataPrototype</code>.\n</li><li><strong>VariableDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>AutosarDataPrototype</code>.\n</li><li><strong>ApplicationCompositeElementDataPrototype</strong> (Package <code>DataPrototypes</code>): Spezialisierung von <code>DataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenzablauf oder zeitliches Protokoll dargestellt. Die Instanzreferenz bildet zur Laufzeit- bzw. Modellierungsphase einen geordneten Pfad («AtpInstanceRef») ab: Ausgehend von der Basis (<code>SwComponentType</code>) wird über eine Folge von Subkomponenten-Instanzen (<code>contextComponent</code>), einen konkreten Port (<code>contextPortPrototype</code>), optional ein Wurzel-Datenelement (<code>rootVariableDataPrototype</code>) sowie tiefer geschachtelte Datenelementstrukturen (<code>contextDataPrototype</code>) auf das finale Ziel-Datenelement (<code>targetDataProtoype</code>) traversiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Werkzeuge und Modelltransformatoren, die Instanzen von Variablen innerhalb von AUTOSAR-Software-Komponenten für Timing-Beschreibungen referenzieren. Wesentliche Modellierungsregeln:</p>\n<ul class=\"fig-list\"><li>Jede <code>AutosarVariableInstance</code> muss exakt eine <code>VariableInComponentInstanceRef</code> besitzen.\n</li><li>Das Ziel (<code>targetDataProtoype</code>) ist strikt einfach (<code>1</code>) und redefiniert <code>atpTarget</code>.\n</li><li>Der Kontextpfad erfordert zwingend genau einen <code>PortPrototype</code> (<code>contextPortPrototype 1</code>).\n</li><li>Schachtelungen über Komponenten (<code>contextComponent</code>) und hierarchische Datenelemente (<code>contextDataPrototype</code>) sind geordnet (<code>{ordered}</code>) und als Teilmengen von <code>atpContextElement</code> modelliert.\n</li><li><code>base</code> ist abgeleitet (<code>«atpDerived»</code>) und redefiniert <code>atpBase</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-db3e967f9152f14c", "to": "FIG-d703ea284e87bdea", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Kreuzung der Assoziationslinie <code>+contextComponent</code> mit den vertikalen Verbindungslinien zu <code>+rootVariableDataPrototype</code> und <code>+contextPortPrototype</code>: Hinzufügen von Leitungsbrücken (Bögen zur visuellen Entflechtung sich kreuzender Kanten).\n</li></ul>"}, {"from": "FIG-d703ea284e87bdea", "to": "FIG-2ef3eb2e618bf6a0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
